DECLARE @TopN INT = 5;

IF (SELECT COUNT(*) AS [rowCount] FROM AccTransactionLines  WITH(NOLOCK) ) > 10000
SET @TopN = 1;

SELECT TOP (@TopN) AL_LineType FROM AccTransactionLines WITH(NOLOCK) WHERE AL_LineType NOT IN ( 'CST','REV','ACR','WIP','UCT','AJL','DPY','GJL','RJL','DRC' ) OPTION (MAXDOP 1);


